package io.github.kazeevn.kokorotts.engine

import org.junit.Assert.assertTrue
import org.junit.Test
import java.nio.ByteBuffer
import java.nio.ByteOrder
import kotlin.math.PI
import kotlin.math.abs

/** Dsp.kt vs convert/host_dsp.py golden data (generated by convert/dsp_golden.py). */
class DspTest {
    private fun load(name: String): FloatArray {
        val bytes = javaClass.getResourceAsStream("/dsp/$name.bin")!!.readBytes()
        val fb = ByteBuffer.wrap(bytes).order(ByteOrder.LITTLE_ENDIAN).asFloatBuffer()
        return FloatArray(fb.remaining()).also { fb.get(it) }
    }

    private fun maxDiff(a: FloatArray, b: FloatArray, from: Int = 0, n: Int = a.size): Double {
        var m = 0.0
        for (i in from until from + n) m = maxOf(m, abs(a[i] - b[i]).toDouble())
        return m
    }

    private val f0 = load("f0")
    private val dsp = Dsp(load("w"), load("b")[0], FloatArray(3), 0f, FloatArray(3), 0f, withNoise = false)

    @Test fun harmonicSource() {
        val src = dsp.harmonicSource(f0, f0.size)
        val ref = load("src")
        val d = maxDiff(src, ref)
        println("harmonic source max diff $d")
        assertTrue(d < 1e-4)
    }

    @Test fun stft() {
        val src = load("src")
        val nFrames = src.size / 5 + 1
        val dst = FloatArray(24 * nFrames)
        dsp.stftInto(src, dst, nFrames)
        val mag = load("mag")
        val ph = load("ph")
        val dm = maxDiff(dst, mag, 0, 11 * nFrames)
        var dp = 0.0
        for (i in 0 until 11 * nFrames) {
            if (mag[i] < 1e-3) continue // phase of ~zero bins is numerically arbitrary
            var e = abs(dst[11 * nFrames + i] - ph[i]).toDouble()
            if (e > PI) e = 2 * PI - e
            dp = maxOf(dp, e)
        }
        println("stft mag diff $dm phase diff $dp")
        assertTrue(dm < 1e-4 && dp < 1e-3)
    }

    @Test fun istft() {
        val x = load("x")
        val frames = x.size / 22
        val y = dsp.istft(x, frames, frames)
        val ref = load("y")
        val d = maxDiff(y, ref)
        println("istft max diff $d (n=${y.size} vs ${ref.size})")
        assertTrue(y.size == ref.size && d < 1e-4)
    }
}
